From b0e7576227ea0e2247130b3fdd28543c0d9b8104 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 22:49:39 +0100
Subject: [PATCH] kcms/wallpaper: add an option to also set the wallpaper for
 the lock screen

Using the same wallpaper on the desktop and on the lock screen meant
setting it twice in two different pages. Add a "Set for lock screen"
switch next to "Set for all screens" that also applies it there.

BUG: 367666
---
 kcms/wallpaper/ui/main.qml         | 12 ++++++++++
 kcms/wallpaper/wallpapermodule.cpp | 35 +++++++++++++++++++++++++++++-
 kcms/wallpaper/wallpapermodule.h   |  6 +++++
 3 files changed, 52 insertions(+), 1 deletion(-)

diff --git a/kcms/wallpaper/ui/main.qml b/kcms/wallpaper/ui/main.qml
index 55f5d58d7b..40b10e2e4b 100644
--- a/kcms/wallpaper/ui/main.qml
+++ b/kcms/wallpaper/ui/main.qml
@@ -51,6 +51,18 @@ Kirigami.ScrollablePage {
                 visible: allScreensAction.visible
                 onToggled: allScreensAction.trigger()
             }
+        },
+        Kirigami.Action {
+            id: lockScreenAction
+            text: i18nc("@option:check Also set the wallpaper for the lock screen", "Set for lock screen")
+            checkable: true
+            checked: kcm.lockScreen
+            onTriggered: kcm.lockScreen = checked
+            displayComponent: QQC2.Switch {
+                text: lockScreenAction.text
+                checked: lockScreenAction.checked
+                onToggled: lockScreenAction.trigger()
+            }
         }
     ]

diff --git a/kcms/wallpaper/wallpapermodule.cpp b/kcms/wallpaper/wallpapermodule.cpp
index 06ef4d18b5..e660cd0adb 100644
--- a/kcms/wallpaper/wallpapermodule.cpp
+++ b/kcms/wallpaper/wallpapermodule.cpp
@@ -361,6 +361,25 @@ void WallpaperModule::save()
         }
     }

+    if (m_lockScreen) {
+        KSharedConfigPtr screenLockerConfig = KSharedConfig::openConfig(u"kscreenlockerrc"_s);
+        KConfigGroup greeterGroup = screenLockerConfig->group(u"Greeter"_s);
+        greeterGroup.writeEntry("WallpaperPlugin", m_currentWallpaperPlugin);
+        KConfigGroup lockScreenWallpaperGroup = greeterGroup.group(u"Wallpaper"_s).group(m_currentWallpaperPlugin).group(u"General"_s);
+        for (const auto &[key, value] : params.asKeyValueRange()) {
+            const KConfigSkeletonItem *item = m_configLoader->findItemByName(key);
+            if (!item) {
+                continue;
+            }
+            if (value == item->getDefault()) {
+                lockScreenWallpaperGroup.deleteEntry(item->key());
+            } else {
+                lockScreenWallpaperGroup.writeEntry(item->key(), value);
+            }
+        }
+        screenLockerConfig->sync();
+    }
+
     setRepresentsDefaults(isDefault());
     Q_EMIT settingsSaved();
 }
@@ -384,11 +403,25 @@ void WallpaperModule::setAllScreens(const bool allScreens)
 {
     if (allScreens != m_allScreens) {
         m_allScreens = allScreens;
-        setNeedsSave(m_allScreens || m_configLoader->isSaveNeeded() || m_loadedWallpaperplugin != m_currentWallpaperPlugin);
+        setNeedsSave(m_allScreens || m_lockScreen || m_configLoader->isSaveNeeded() || m_loadedWallpaperplugin != m_currentWallpaperPlugin);
         Q_EMIT allScreensChanged();
     }
 }

+bool WallpaperModule::lockScreen() const
+{
+    return m_lockScreen;
+}
+
+void WallpaperModule::setLockScreen(const bool lockScreen)
+{
+    if (lockScreen != m_lockScreen) {
+        m_lockScreen = lockScreen;
+        setNeedsSave(m_lockScreen || m_allScreens || m_configLoader->isSaveNeeded() || m_loadedWallpaperplugin != m_currentWallpaperPlugin);
+        Q_EMIT lockScreenChanged();
+    }
+}
+
 QList<QScreen *> WallpaperModule::screens() const
 {
     return qGuiApp->screens();;
diff --git a/kcms/wallpaper/wallpapermodule.h b/kcms/wallpaper/wallpapermodule.h
index a1777faaac..a6a32e5dac 100644
--- a/kcms/wallpaper/wallpapermodule.h
+++ b/kcms/wallpaper/wallpapermodule.h
@@ -28,6 +28,7 @@ class WallpaperModule : public KQuickConfigModule

     Q_PROPERTY(QString currentWallpaper READ currentWallpaperPlugin WRITE setCurrentWallpaperPlugin NOTIFY currentWallpaperPluginChanged)
     Q_PROPERTY(bool allScreens READ allScreens WRITE setAllScreens NOTIFY allScreensChanged)
+    Q_PROPERTY(bool lockScreen READ lockScreen WRITE setLockScreen NOTIFY lockScreenChanged)
     Q_PROPERTY(QString wallpaperPluginSource READ wallpaperPluginSource NOTIFY currentWallpaperPluginChanged)
     Q_PROPERTY(PlasmaQuick::ConfigModel *wallpaperConfigModel READ wallpaperConfigModel CONSTANT)

@@ -53,6 +54,9 @@ public:
     bool allScreens() const;
     void setAllScreens(const bool allScreens);

+    bool lockScreen() const;
+    void setLockScreen(const bool lockScreen);
+
     void load() override;
     void save() override;
     void defaults() override;
@@ -63,6 +67,7 @@ Q_SIGNALS:
     void selectedScreenChanged();
     void screensChanged();
     void allScreensChanged();
+    void lockScreenChanged();
     void settingsSaved();

 public Q_SLOTS:
@@ -92,6 +97,7 @@ private:
     QString m_containmentIdx;
     QString m_defaultWallpaper;
     bool m_allScreens = false;
+    bool m_lockScreen = false;
 };

 #endif // WALLPAPERMODULE_H
